import pandas as pd
import json
import os
import re

dfs = []
for p in DATA_PATH:
    if p.endswith(('.xlsx', '.xls')):
        df_temp = pd.read_excel(p, skiprows=2)
    else:
        df_temp = pd.read_csv(p, skiprows=2)
    # 提取文件名中的月份（支持中文"X月"、数字"X"、"YYYY-MM"等常见格式）
    filename = os.path.basename(p)
    month_match = re.search(r'(\d{1,2})[月\-\.\/_ ]?(\d{4})|(\d{4})[年\-\.\/_ ]?(\d{1,2})[月]|(\d{1,2})[月]|(\d{4})[-/](\d{1,2})', filename)
    month_num = 0
    if month_match:
        groups = month_match.groups()
        # 优先匹配：X月、YYYY-MM、MM、YYYY年M月等
        for g in groups:
            if g and g.isdigit():
                m = int(g)
                if 1 <= m <= 12:
                    month_num = m
                    break
        if month_num == 0:
            # 尝试中文数字月（一月、二月...十二月）
            cn_month_map = {'一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6,
                           '七': 7, '八': 8, '九': 9, '十': 10, '十一': 11, '十二': 12}
            for cn, num in cn_month_map.items():
                if cn + '月' in filename:
                    month_num = num
                    break
    # 添加辅助列：文件路径、提取的月份
    df_temp['_file_path'] = p
    df_temp['_month'] = month_num
    dfs.append(df_temp)

if not dfs:
    df = pd.DataFrame()
else:
    df = pd.concat(dfs, ignore_index=True)

# 处理数字列：转numeric并fillna(0)
for col in df.columns:
    if df[col].dtype == 'object':
        # 尝试转为数字（跳过日期类列，但此处暂不区分，统一按规则处理；后续日期列会单独处理）
        converted = pd.to_numeric(df[col], errors='coerce')
        if not converted.isna().all():  # 确实能转为数字
            df[col] = converted.fillna(0)

# 查找可能的出勤天数列（模糊匹配：包含'出勤'、'天数'、'工作日'、'attendance'等关键词，且为数值型）
attendance_cols = []
for col in df.columns:
    col_lower = str(col).lower()
    if any(kw in col_lower for kw in ['出勤', '天数', '工作日', 'attendance', 'days', 'workday', 'presence']):
        # 检查该列是否主要为数字（非全空、非全文本）
        if pd.api.types.is_numeric_dtype(df[col]) or not df[col].dropna().apply(lambda x: isinstance(x, str)).all():
            attendance_cols.append(col)

# 若未找到明确列，尝试所有数值列中取最大可能的整数型列（如含大量0-31值）
if not attendance_cols:
    numeric_cols = df.select_dtypes(include=['number']).columns.tolist()
    for col in numeric_cols:
        s = pd.to_numeric(df[col], errors='coerce').dropna()
        if len(s) > 0 and s.min() >= 0 and s.max() <= 31 and s.apply(lambda x: x == int(x) if pd.notna(x) else True).all():
            attendance_cols.append(col)
            break

# 默认列名备选
if not attendance_cols:
    possible_names = ['出勤天数', '实际出勤', '出勤', '天数', '工作天数', 'attendance_days', 'days']
    for name in possible_names:
        if name in df.columns:
            attendance_cols.append(name)
            break

# 若仍无，则用第一个数值列
if not attendance_cols:
    numeric_cols = df.select_dtypes(include=['number']).columns.tolist()
    if numeric_cols:
        attendance_cols.append(numeric_cols[0])

# 汇总每个文件的出勤天数总和
result_data = []
for p in DATA_PATH:
    # 提取该文件对应的数据子集
    df_sub = df[df['_file_path'] == p].copy()
    total_attendance = 0
    if attendance_cols and attendance_cols[0] in df_sub.columns:
        col = attendance_cols[0]
        # 转数字并求和
        vals = pd.to_numeric(df_sub[col], errors='coerce')
        total_attendance = vals.sum()
    # 提取文件名中的月份用于排序
    filename = os.path.basename(p)
    month_match = re.search(r'(\d{1,2})[月\-\.\/_ ]?(\d{4})|(\d{4})[年\-\.\/_ ]?(\d{1,2})[月]|(\d{1,2})[月]|(\d{4})[-/](\d{1,2})', filename)
    month_num = 0
    if month_match:
        groups = month_match.groups()
        for g in groups:
            if g and g.isdigit():
                m = int(g)
                if 1 <= m <= 12:
                    month_num = m
                    break
        if month_num == 0:
            cn_month_map = {'一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6,
                           '七': 7, '八': 8, '九': 9, '十': 10, '十一': 11, '十二': 12}
            for cn, num in cn_month_map.items():
                if cn + '月' in filename:
                    month_num = num
                    break
    result_data.append({
        'file': p,
        'month': month_num,
        'total_attendance_days': float(total_attendance) if pd.notna(total_attendance) else 0.0
    })

# 按月份排序（1月到12月），未识别月份的排最后
result_data.sort(key=lambda x: (x['month'] if x['month'] != 0 else 99))

# 构建结果
result = {
    "status": "success",
    "summary": f"共处理{len(DATA_PATH)}个文件，汇总出勤天数",
    "data": result_data
}

print(json.dumps(result, ensure_ascii=False, default=str))
