        # Try to convert to numeric only if not obviously datetime-like
        converted = pd.to_numeric(df[col], errors='coerce')
        if not converted.isna().all():  # Only replace if some values converted successfully
            df[col] = converted.fillna(0)

# Convert datetime columns to string format '%Y-%m-%d'
for col in df.columns:
    if df[col].dtype == 'object':
        try:
            dt_series = pd.to_datetime(df[col], errors='raise')
            df[col] = dt_series.dt.strftime('%Y-%m-%d')
        except (ValueError, TypeError, pd.errors.OutOfBoundsDatetime):
            pass

# Identify potential attendance day columns: look for columns containing '出勤' or '天数' or 'days' etc., or numeric columns likely representing days
# Heuristic: prefer columns with names like '出勤天数', '出勤', 'attendance', 'days', '工作天数', '实际出勤' etc.
attendance_cols = []
for col in df.columns:
    col_lower = str(col).strip().lower()
    if any(kw in col_lower for kw in ['出勤天数', '出勤', 'attendance', 'days', '工作天数', '实际出勤', '出勤日', '出勤日数', '天数']):
        attendance_cols.append(col)

# If no heuristic match, fallback to numeric columns (excluding obvious ID/name columns)
if not attendance_cols:
    # Exclude columns that are likely identifiers or text
    for col in df.columns:
        if pd.api.types.is_numeric_dtype(df[col]):
            # Avoid columns with very few unique values (e.g., status codes) and very high cardinality text columns
            if df[col].nunique() > 1 and df[col].nunique() < len(df) * 0.9:
                attendance_cols.append(col)

# Sum all identified attendance columns row-wise, then sum total
total_days = 0
if attendance_cols:
    # Sum across rows for each attendance column, then sum all
    for col in attendance_cols:
        # Ensure numeric
        ser = pd.to_numeric(df[col], errors='coerce').fillna(0)
        total_days += ser.sum()
else:
    # Fallback: sum all numeric columns
    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) > 0:
        total_days = df[numeric_cols].sum().sum()
    else:
        total_days = 0

result = {
    "status": "success",
    "summary": f"出勤总天数为{int(total_days)}天",
    "data": {"total_attendance_days": int(total_days)}
}

