import pandas as pd
import json
import re

# 读取数据
if isinstance(DATA_PATH, str):
    if DATA_PATH.endswith(('.xlsx', '.xls')):
        df = pd.read_excel(DATA_PATH, skiprows=2)
    else:
        df = pd.read_csv(DATA_PATH, skiprows=2)
else:
    dfs = []
    for p in DATA_PATH:
        if p.endswith(('.xlsx', '.xls')):
            dfs.append(pd.read_excel(p, skiprows=2))
        else:
            dfs.append(pd.read_csv(p, skiprows=2))
    df = pd.concat(dfs, ignore_index=True)

# 处理数字列
for col in df.select_dtypes(include=['object']).columns:
    if df[col].dtype == 'object':
        converted = pd.to_numeric(df[col], errors='coerce')
        if not converted.isna().all():
            df[col] = converted.fillna(0)

# 提取月份：从文件名中匹配“\d{1,2}月”或“\d{1,2}月份”，取数字部分，映射为1-12整数
months = []
for p in (DATA_PATH if isinstance(DATA_PATH, list) else [DATA_PATH]):
    match = re.search(r'(\d{1,2})[月份]', p)
    if match:
        month_num = int(match.group(1))
        if 1 <= month_num <= 12:
            months.append(month_num)
# 若未提取到任何月份，用默认1-12顺序（但需保证至少有一个有效月份）
if not months:
    months = list(range(1, 13))

# 按月份分组汇总出勤总天数：假设存在“出勤天数”、“出勤”、“天数”等常见列名，优先匹配精确列名
attendance_col = None
for candidate in ['出勤天数', '出勤', '天数', '实际出勤天数', '应出勤天数', '出勤日期数']:
    if candidate in df.columns:
        attendance_col = candidate
        break
if attendance_col is None:
    # 尝试模糊匹配含“出勤”和“天数”的列
    for col in df.columns:
        if '出勤' in str(col) and ('天数' in str(col) or 'days' in str(col).lower() or 'day' in str(col).lower()):
            attendance_col = col
            break
if attendance_col is None:
    # 取第一个数值型列作为出勤天数（fallback）
    numeric_cols = df.select_dtypes(include=['number']).columns.tolist()
    if numeric_cols:
        attendance_col = numeric_cols[0]

# 汇总逻辑：按月份顺序（1~12）生成结果，每个月份对应其所有文件中该月的出勤天数之和
# 由于不同文件可能对应不同月份，我们为每个文件分配一个月份（取第一个匹配的），然后按该月累加
month_to_files = {}
for p in (DATA_PATH if isinstance(DATA_PATH, list) else [DATA_PATH]):
    match = re.search(r'(\d{1,2})[月份]', p)
    if match:
        m = int(match.group(1))
        if 1 <= m <= 12:
            if m not in month_to_files:
                month_to_files[m] = []
            month_to_files[m].append(p)

# 初始化12个月结果
monthly_sum = {i: 0.0 for i in range(1, 13)}

