    if df[col].dtype == 'object':
        converted = pd.to_numeric(df[col], errors='coerce')
        if not converted.isna().all():
            df[col] = converted.fillna(0)

# 查找日期列（含'日期'、'时间'、'date'、'time'等关键词的列）
date_cols = [col for col in df.columns if any(kw in str(col).lower() for kw in ['日期', '时间', 'date', 'time'])]
for col in date_cols:
    if col in df.columns:
        try:
            df[col] = pd.to_datetime(df[col], errors='coerce').dt.strftime('%Y-%m-%d')
        except:
            pass

# 查找出勤天数列（含'出勤'、'天数'、'attendance'、'days'等关键词，且为数值型或可转数值）
attendance_cols = []
for col in df.columns:
    col_lower = str(col).lower()
    if any(kw in col_lower for kw in ['出勤', 'attendance', 'days', '天数', '工时', 'hours']) and '月' not in col_lower:
        # 尝试转换为数值并检查是否实际含数字数据
        numeric_series = pd.to_numeric(df[col], errors='coerce')
        if numeric_series.count() > 0:
            attendance_cols.append(col)
            df[col] = numeric_series.fillna(0)

# 若未找到明确出勤天数列，则尝试所有数值列中寻找最可能的（非ID、非年份、非序号类）
if not attendance_cols:
    possible_num_cols = df.select_dtypes(include=['number']).columns.tolist()
    # 过滤掉明显非出勤的列（如ID、年份、序号）
    attendance_cols = [
        col for col in possible_num_cols
        if not any(kw in str(col).lower() for kw in ['id', '编号', '序号', 'year', '年', 'code', '编码'])
    ]
    if not attendance_cols:
        # 退回到第一列数值列
        num_cols = df.select_dtypes(include=['number']).columns
        if len(num_cols) > 0:
            attendance_cols = [num_cols[0]]

# 查找月份列（含'月'、'month'等关键词）
month_cols = [col for col in df.columns if any(kw in str(col).lower() for kw in ['月', 'month'])]
month_col = None
if month_cols:
    # 优先选名称最匹配的
    for c in month_cols:
        if '月' in str(c) and '年' not in str(c):
            month_col = c
            break
    if not month_col:
        month_col = month_cols[0]

# 若无显式月份列，尝试从日期列提取月份
if not month_col and date_cols:
    date_col = date_cols[0]
    try:
        # 提取月份
        df['month_extracted'] = pd.to_datetime(df[date_col], errors='coerce').dt.month
        month_col = 'month_extracted'
    except:
        pass

# 若仍无月份列，尝试用索引或默认全为1月（但需报错处理）
if not month_col:
    # 创建默认月份列：假设全部为1月（但更合理是跳过或报错）——按需求必须输出1-12月，故需构造完整月份维度
    # 我们将尝试生成1-12月汇总，若无月份信息则所有数据归入1月，其余为0
    month_col = 'default_month'
    df[month_col] = 1

# 确保月份列为整数
df[month_col] = pd.to_numeric(df[month_col], errors='coerce').fillna(1).astype(int)
df[month_col] = df[month_col].clip(1, 12)

# 选择第一个出勤列
attendance_col = attendance_cols[0] if attendance_cols else None

if attendance_col is None:
    result = {
        "status": "error",
        "summary": "未找到出勤天数列",
        "data": []
    }
else:
    # 按月份汇总出勤总天数
    # 确保月份为1-12，缺失月份补0
    if month_col in df.columns:
        # 分组求和
        monthly_sum = df.groupby(month_col)[attendance_col].sum().reindex(range(1, 13), fill_value=0).round(2)
        # 转为字典，键为"1月"..."12月"
        data_list = [{"month": f"{m}月", "total_days": float(monthly_sum[m])} for m in range(1, 13)]
        result = {
            "status": "success",
            "summary": "按月份汇总出勤总天数完成",
            "data": data_list
        }
    else:
        result = {
            "status": "error",
            "summary": "未找到有效月份列",
            "data": []
        }

print(json.dumps(result, ensure_ascii=False, default=str))
